#include <Cellerator/compiler/lto/implement_program_level_semantic_planning_ir_v1.hh>
#include <algorithm>
namespace cellerator::compiler::lto::v1 { namespace { bool eq(const artifact_identity_v1&a,const artifact_identity_v1&b){return a.high==b.high&&a.low==b.low;} void ids(std::vector<artifact_identity_v1>&d,const std::vector<artifact_identity_v1>&s){for(auto x:s)if(std::none_of(d.begin(),d.end(),[&](auto y){return eq(x,y);}))d.push_back(x);} void strs(std::vector<std::string>&d,const std::vector<std::string>&s){for(const auto&x:s)if(std::find(d.begin(),d.end(),x)==d.end())d.push_back(x);} }
program_ir_merge_status_v1 merge_program_semantic_planning_ir_v1(const std::vector<field_program_ir_v1>&fs,program_semantic_planning_ir_v1*r)noexcept{if(!r)return program_ir_merge_status_v1::missing_source;*r={};for(const auto&f:fs){if(!f.exported)continue;if(f.source.empty())return program_ir_merge_status_v1::missing_source;if(std::any_of(r->fields.begin(),r->fields.end(),[&](const auto&x){return eq(x.identity,f.identity);}))return program_ir_merge_status_v1::duplicate_field;r->fields.push_back(f);r->source_trace.push_back(f.source);ids(r->profiles,f.profiles);ids(r->shared_artifacts,f.shared_artifacts);strs(r->external_effects,f.external_effects);strs(r->program_constraints,f.program_constraints);}for(const auto&f:r->fields)for(auto c:f.calls)if(std::none_of(r->fields.begin(),r->fields.end(),[&](const auto&x){return eq(c,x.identity);}))return program_ir_merge_status_v1::missing_call_target;return program_ir_merge_status_v1::valid;}
}
